11: }
12: 
13: class CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
15: 
16:   late final AnimationController _fadeController;
17: 
18:   late Future<List<CurrencyModel>> _currencyListFuture;
19: 
20:   List<CurrencyModel> _allCurrencies = [];
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _initData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _filteredCurrenciesNotifier.dispose();
32:     _fadeController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _fadeController = AnimationController(
38:       duration: Duration(milliseconds: 400),
39:       vsync: this,
40:     );
41:   }
42: 
43:   void _initData() {
44:     final currencyRepository = context.read<CurrencyRepository>();
45: 
46:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
47:       final List<CurrencyModel> value = page.items;
48:       _allCurrencies = value;
49:       _filteredCurrenciesNotifier = ValueNotifier(value);
50: 
51:       _fadeController.forward(); // запускаем анимацию
52: 
53:       currencyRepository.saveCurrencyList(value);
54: 
55:       return value;
56:     });
57:   }
58: 
59:   /// Принудительно обновить данные из сети.
60:   void refresh() {
61:     setState(() {
62:       _initData();
63:     });
64:   }
65: 
66:   void _filterCurrencies(String query) {
67:     final String lowerQuery = query.toLowerCase();
68:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
69:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
70:     });
71: 
72:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
73:   }
74: 
75:   @override
76:   Widget build(BuildContext context) {
77:     return Scaffold(
78:       appBar: AppBar(title: Text(context.loc.currencyRate)),
79:       body: FutureBuilder(
80:         future: _currencyListFuture,
81:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
82:           final List<CurrencyModel>? data = snapshot.data;
83:           if (data == null) return const SizedBox.shrink();
84: 
85:           return FadeTransition(
86:             opacity: _fadeController.view,
87:             child: Column(
88:               children: [
89:                 Padding(
90:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
91:                   child: SearchView(onChanged: _filterCurrencies),
92:                 ),
93:                 Expanded(
94:                   child: ValueListenableBuilder<List<CurrencyModel>>(
95:                     valueListenable: _filteredCurrenciesNotifier,
96:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
97:                       return ListView.builder(
98:                         itemCount: data.length,
99:                         itemBuilder: (BuildContext context, int index) {
100:                           final CurrencyModel currency = data[index];
101: 
102:                           return Padding(
103:                             key: ValueKey(currency.id),
104:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
105:                             child: CurrencyCard(model: currency),
106:                           );
107:                         },
108:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
109:                       );
110:                     },
111:                   ),
112:                 ),
113:               ],
114:             ),
115:           );
116:         },
117:       ),
118:     );
119:   }
120: }

